regex_added:
(?x)
        \b(?:
            # International or explicitly formatted numbers
            (?:\+?\d{1,3}[-.\s]?)?\(?\d{3}\)?[-.\s]?\d{3}[-.\s]?\d{4}
            |
            # Phone numbers following explicit indicators like 'phone:', 'call:', 'at'
            (?:phone|cell|mobile|call|text|number)[:\s]+\+?\d{1,4}[-.\s]?\(?\d{1,3}\)?[-.\s]?\d{3,4}[-.\s]?\d{4}
        )
        (?:\s*(?:ext|x)\.?\s*\d+)?\b
